// tolerant category parse
const VALID = ['美妆个护','家居家装','母婴育儿','时尚穿搭','美食','萌宠动物','3C数码','旅游/户外'];
const raw = $input.first().json.choices?.[0]?.message?.content || '{}';
let parsed = {};
try { parsed = JSON.parse(raw); } catch(e) {
  const m = raw.match(/\{[\s\S]*\}/);
  if (m) { try { parsed = JSON.parse(m[0]); } catch(_){} }
}
let cat = parsed.category || parsed.result || '';
// direct match?
if (!VALID.includes(cat)) {
  // scan raw text for any valid cat
  cat = VALID.find(v => raw.includes(v)) || '时尚穿搭';
}
return [{ json: { category: cat, ...$('Extract Params').item.json }}];

const fs = require('fs');
const path = require('path');
const prev = $input.first().json;
const category = prev.category;
const corpusDir = '/home/david/xhs-corpus';

// 1. Read hot_notes.jsonl, filter by category, random up to 3
let hotAll = [];
try { hotAll = fs.readFileSync(`${corpusDir}/hot_notes.jsonl`,'utf8').split('\n').filter(l=>l.trim()).map(l=>JSON.parse(l)); } catch(e) {}
const hotByCat = hotAll.filter(n => n.category === category);
const shuffledHot = [...hotByCat].sort(() => Math.random() - 0.5);
const hotSamples = shuffledHot.slice(0, 3).map(n => ({
  title: n.title,
  metrics_raw: n.metrics_raw || '',
  creator: n.creator
}));

// 2. Read seed_notes/*.md, filter by category (YAML frontmatter), random up to 2
let seedFiles = [];
try { seedFiles = fs.readdirSync(`${corpusDir}/seed_notes`).filter(f=>f.endsWith('.md')); } catch(e) {}
const matchingSeeds = [];
for (const f of seedFiles) {
  try {
    const content = fs.readFileSync(`${corpusDir}/seed_notes/${f}`,'utf8');
    // Parse YAML frontmatter
    const fmMatch = content.match(/^---\n([\s\S]*?)\n---\n([\s\S]*)$/);
    if (!fmMatch) continue;
    const fmText = fmMatch[1];
    const body = fmMatch[2].trim();
    const catMatch = fmText.match(/^category:\s*(.+)$/m);
    if (catMatch && catMatch[1].trim() === category) {
      matchingSeeds.push({ file: f, body: body });
    }
  } catch(e) {}
}
const shuffledSeeds = matchingSeeds.sort(() => Math.random() - 0.5);
const seedSamples = shuffledSeeds.slice(0, 2);

// 3. Read category_style.md, extract section for this category
let styleSection = '';
try {
  const styleMd = fs.readFileSync(`${corpusDir}/category_style.md`,'utf8');
  const regex = new RegExp(`## ${category}\\n([\\s\\S]*?)(?=\\n## |$)`);
  const m = styleMd.match(regex);
  if (m) styleSection = m[1].trim();
} catch(e) {}
if (!styleSection) styleSection = '(该类目无 style 数据, 参考通用小红书风格)';

return [{ json: {
  category,
  style_section: styleSection,
  hot_samples: hotSamples,
  seed_samples: seedSamples,
  hot_count: hotSamples.length,
  seed_count: seedSamples.length,
  ...prev
}}];

// Build hauhau prompt with category-inject + few-shot
const p = $input.first().json;
const params = $('Extract Params').item.json;
const theme = params.theme;
const num_images = params.num_images || 3;

const sysPrompt = `你是专业的小红书爆款文案师。严格遵守: (1) 标题15字内, 带emoji, 有钩子; (2) 正文250-500字, 短句多段, emoji点缀, 有场景感; (3) 结尾3-5个疑问句或CTA; (4) 8-10个中文tag; (5) ${num_images}张配图的英文prompt, 每张60词内, 描述具体场景+光线+构图, 覆盖不同角度/景别.\n\n**严格禁止**: 正文body里不允许出现以 # 开头的行或裸tag, tag只在返回JSON的tags数组里, 不许在body里重复; 不许把tags再以 ## 双井号形式重复输出.\n\n严格返回JSON: {\"title\":\"...\", \"body\":\"...\", \"tags\":[\"tag1\",...], \"image_prompts\":[\"en1\",...共${num_images}个]}`;

let userPrompt = `主题: ${theme}\n\n本次为「${p.category}」类目笔记, 请参考本类目的爆款风格特征:\n\n${p.style_section}`;

if (p.hot_samples && p.hot_samples.length > 0) {
  userPrompt += `\n\n本类目近期爆款方向 (只作趋势参考, 不必字面模仿):`;
  for (const h of p.hot_samples) {
    userPrompt += `\n- 【${h.creator}】${h.title}` + (h.metrics_raw ? ` (${h.metrics_raw})` : '');
  }
}

if (p.seed_samples && p.seed_samples.length > 0) {
  userPrompt += `\n\n参考真实优质样本 (风格模仿源):\n\n`;
  userPrompt += p.seed_samples.map((s,i) => `样本${i+1}:\n${s.body}`).join('\n\n---\n\n');
}

const chatBody = {
  model: 'Qwen3.6-35B-Hauhau',
  temperature: 0.85,
  max_tokens: 9000,
  response_format: { type: 'json_object' },
  messages: [
    { role: 'system', content: sysPrompt },
    { role: 'user', content: userPrompt }
  ]
};

return [{ json: { chat_body: chatBody, theme, num_images, ...p }}];

const fs = require('fs');
const raw = $input.first().json.choices[0].message.content;
const data = JSON.parse(raw);
const prev = $('Build Hauhau Prompt').item.json;
let body = (data.body || '').split('\n').filter(line => !/^\s*#+\s*[\u4e00-\u9fa5]/.test(line)).join('\n').replace(/\n{3,}/g, '\n\n').trim();
const tagsClean = [...new Set((data.tags || []).map(t => t.replace(/^#+/, '').trim()).filter(Boolean))];
const ts = new Date().toISOString().slice(0,19).replace(/[-:T]/g,'');
const draftDir = `/home/david/xhs-drafts/${ts}`;
fs.mkdirSync(draftDir, { recursive: true });
const mdPath = `${draftDir}/note.md`;
const md = `# ${data.title}\n\n${body}\n\n${tagsClean.map(t=>'#'+t).join(' ')}\n\n---\n_生成基于 ${prev.category} 类目, 参考 ${prev.hot_count} hot + ${prev.seed_count} seed_\n`;
fs.writeFileSync(mdPath, md);
const prompts = data.image_prompts || [];
const n = Math.min(prev.num_images, prompts.length);
const result = [];
for (let i = 0; i < n; i++) {
  result.push({ json: { prompt: prompts[i], index: i + 1, total: n, draft_dir: draftDir, md_path: mdPath, title: data.title, body: body, tags: tagsClean, category: prev.category, hot_count: prev.hot_count, seed_count: prev.seed_count, tg_chat_id: prev.tg_chat_id, tg_bot_token: prev.tg_bot_token }});
}
return result;

const item = $input.first().json;
const seed = Math.floor(Math.random() * 1000000000);
const workflow = {
  '1': {class_type:'UNETLoader', inputs:{unet_name:'qwen_image_fp8_e4m3fn.safetensors', weight_dtype:'default'}},
  '2': {class_type:'CLIPLoader', inputs:{clip_name:'qwen_2.5_vl_7b_fp8_scaled.safetensors', type:'qwen_image'}},
  '3': {class_type:'VAELoader', inputs:{vae_name:'qwen_image_vae.safetensors'}},
  '4': {class_type:'ModelSamplingAuraFlow', inputs:{model:['1',0], shift:3.1}},
  '5': {class_type:'CLIPTextEncode', inputs:{clip:['2',0], text:item.prompt}},
  '6': {class_type:'CLIPTextEncode', inputs:{clip:['2',0], text:''}},
  '7': {class_type:'EmptySD3LatentImage', inputs:{width:1024, height:1024, batch_size:1}},
  '8': {class_type:'KSampler', inputs:{model:['4',0], positive:['5',0], negative:['6',0], latent_image:['7',0], seed, steps:20, cfg:2.5, sampler_name:'euler', scheduler:'simple', denoise:1.0}},
  '9': {class_type:'VAEDecode', inputs:{samples:['8',0], vae:['3',0]}},
  '10': {class_type:'SaveImage', inputs:{images:['9',0], filename_prefix:`n8n-xhs-${item.index}`}}
};
return [{ json: { comfy_body: { prompt: workflow, client_id: 'n8n' }, ...item }}];

const fs = require('fs');
const http = require('http');
const promptId = $input.first().json.prompt_id;
const prev = $('Build Comfy Workflow').item.json;
async function getJson(url) { return new Promise((res, rej) => http.get(url, r => { let d=''; r.on('data',c=>d+=c); r.on('end',()=>{try{res(JSON.parse(d))}catch(e){rej(e)}}); }).on('error', rej)); }
async function getBinary(url) { return new Promise((res, rej) => http.get(url, r => { const c=[]; r.on('data',b=>c.push(b)); r.on('end',()=>res(Buffer.concat(c))); }).on('error', rej)); }
const dl = Date.now() + 900000;
let result = null;
while (Date.now() < dl) {
  const d = await getJson(`http://127.0.0.1:8189/history/${promptId}`);
  if (d[promptId]) {
    const e = d[promptId], st = e.status || {};
    if (st.completed) {
      for (const nid in e.outputs || {}) {
        for (const img of (e.outputs[nid].images || [])) {
          const u = `http://127.0.0.1:8189/view?filename=${img.filename}&subfolder=${img.subfolder||''}&type=output`;
          const buf = await getBinary(u);
          const dest = `${prev.draft_dir}/img-${String(prev.index).padStart(2,'0')}-${img.filename}`;
          fs.writeFileSync(dest, buf);
          result = { saved: dest, filepath: dest };
          break;
        }
        if (result) break;
      }
      break;
    }
    if (st.status_str === 'error') { result = { error: 'workflow error' }; break; }
  }
  await new Promise(r => setTimeout(r, 3000));
}
if (!result) result = { error: 'timeout' };
return [{ json: { ...result, ...prev }}];

